using FlexExtractor;
using System.Diagnostics;
using System.Text.Json;
static partial class Harness {
 static string Setup(string name){var root=Path.Combine(AppContext.BaseDirectory,"selftest-data",name+"-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);typeof(MachineState).GetField("TestRoot",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static)!.SetValue(null,Path.Combine(root,"state"));return root;}
 static Config Configure(string root)=>new(){WatchRoot=Path.Combine(root,"watch"),DispenseItems=[new(){Token="31",StationName="点胶31",SaveFolder=Path.Combine(root,"out")}],SizeStableChecks=0,SizeStableIntervalMs=0,MaxFilesPerPass=100,PollIntervalSec=1,WorkerTimeoutSec=60};
 static string FileName(Config c,int i){var file=Path.Combine(c.WatchRoot,DateTime.Now.ToString("yyyy/MM/dd"),"0031_1_1",(i/50).ToString("D2"),"Request_"+(i%50).ToString("D3")+".xml");Directory.CreateDirectory(Path.GetDirectoryName(file)!);return file;}
 public static int Stress(){try{var root=Setup("stress");var c=Configure(root);c.BindItems=[new(){Token="31",StationName="共享目标组装31",SaveFolder=c.DispenseItems[0].SaveFolder}];var locks=new List<FileStream>();var watch=Stopwatch.StartNew();for(int i=0;i<630;i++){var f=FileName(c,i);File.WriteAllText(f,i>=600&&i<620?"<root>unfinished":"<root><id>"+i+"</id></root>");if(i>=620)locks.Add(new FileStream(f,FileMode.Open,FileAccess.ReadWrite,FileShare.None));}long copied=0,failed=0;using(var owner=new OwnerLease()){for(int pass=0;pass<10;pass++){var r=WorkerRunner.RunAsync(owner,c,"scan",DateTime.UtcNow,CancellationToken.None).GetAwaiter().GetResult();copied+=r.Copied;failed+=r.Failed;Console.WriteLine($"STRESS phase=fault pass={pass} copied={r.Copied} failed={r.Failed} messages={r.Messages.Count}");Program.Check(r.Messages.Count<=32,"messages unbounded");}foreach(var s in locks)s.Dispose();for(int i=600;i<620;i++)File.WriteAllText(FileName(c,i),"<root><id>"+i+"</id></root>");for(int pass=0;pass<10;pass++){var r=WorkerRunner.RunAsync(owner,c,"scan",DateTime.UtcNow,CancellationToken.None).GetAwaiter().GetResult();copied+=r.Copied;failed+=r.Failed;Console.WriteLine($"STRESS phase=recover pass={pass} copied={r.Copied} failed={r.Failed}");}}
  var folder=c.DispenseItems[0].SaveFolder;Program.Check(Directory.GetFiles(folder,"Request*.xml").Length==630,"stress did not recover all630");Program.Check(copied==630,"stress idempotence mismatch");var foreign=Path.Combine(folder,"Request_foreign.xml");File.WriteAllText(foreign,"<foreign/>");var purge=new ScanResult();Ownership.Purge(folder,1,DateTime.UtcNow.AddDays(2),purge);Program.Check(purge.Deleted==630&&File.Exists(foreign),"safe purge mismatch");Program.Check(Directory.GetFiles(c.WatchRoot,"Request*.xml",SearchOption.AllDirectories).Length==630,"source changed");Console.WriteLine($"STRESS RESULT files=630 copied={copied} faultCount={failed} recovered=630 purged={purge.Deleted} foreignPreserved=true sourcePreserved=true elapsedSec={watch.Elapsed.TotalSeconds:F3} root={root}");return 0;
 }catch(Exception ex){Console.WriteLine("STRESS FAIL "+ex);return 1;}}
 // Windows reports ERROR_ACCESS_DENIED for MoveDirectory while an enumerator holds
 // a non-delete-shared directory handle. Retry only known transient IO codes, bounded;
 // a permanent ACL/sharing failure must still fail the harness, never fake recovery.
 static void FixtureIo(Action action){var clock=Stopwatch.StartNew();for(;;){try{action();return;}catch(IOException ex)when((ex.HResult&0xffff) is 5 or 32 or 33 && clock.Elapsed.TotalSeconds<5){Thread.Sleep(50);}}}
 static string ExpectedExport(Config c,string source,string text){var pathHash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(Path.GetFullPath(source).ToUpperInvariant())));var dataHash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(text)));return Path.Combine(c.DispenseItems[0].SaveFolder,Path.GetFileNameWithoutExtension(source)+"__"+pathHash[..16]+"_"+dataHash[..16]+".xml");}
 public static int Soak(int seconds){try{
  if(seconds<15||seconds>3600)throw new ArgumentException("soak seconds must be15..3600");
  var root=Setup("soak");var c=Configure(root);c.MaxLogLines=50;
  for(int i=0;i<30;i++)File.WriteAllText(FileName(c,i),"<root><id>"+i+"</id></root>");
  var engine=new Engine(c);var timer=Stopwatch.StartNew();var samples=new List<object>();
  long initialMemory=0,peakMemory=0,failedBeforeOutage=0;int initialHandles=0,peakHandles=0,cycles=0,recovered=0;bool offline=false;string? recoveryPath=null;string recoveryText="";double recoveryDeadline=0;
  void VerifyRecovery(){if(recoveryPath==null)return;if(File.Exists(recoveryPath)){Program.Check(File.ReadAllText(recoveryPath)==recoveryText,"post-outage marker bytes differ");recovered++;Console.WriteLine($"SOAK RECOVERED cycle={recovered} sec={timer.Elapsed.TotalSeconds:F3} marker={Path.GetFileName(recoveryPath)} copied={engine.Snapshot.Copied} failed={engine.Snapshot.Failed}");recoveryPath=null;}else Program.Check(timer.Elapsed.TotalSeconds<recoveryDeadline,"post-outage new marker was not copied within10seconds");}
  void Restore(){FixtureIo(()=>Directory.Move(c.WatchRoot+".offline",c.WatchRoot));offline=false;Program.Check(engine.Snapshot.Failed>failedBeforeOutage,"source outage was not observed by engine");var marker=FileName(c,1000+cycles);recoveryText="<root><recoveryCycle>"+cycles+"</recoveryCycle></root>";FixtureIo(()=>File.WriteAllText(marker,recoveryText));recoveryPath=ExpectedExport(c,marker,recoveryText);recoveryDeadline=timer.Elapsed.TotalSeconds+10;Console.WriteLine($"SOAK RESTORED cycle={cycles} sec={timer.Elapsed.TotalSeconds:F3}");}
  engine.Start();Console.WriteLine("SOAK START root="+root);
  try{for(int i=0;timer.Elapsed.TotalSeconds<seconds;i++){
   VerifyRecovery();
   if(!offline)FixtureIo(()=>File.WriteAllText(FileName(c,0),i%20==5?"<root>unfinished":"<root><version>"+i+"</version></root>"));
   if(i%40==15&&!offline){Program.Check(recoveryPath==null,"previous recovery not verified");failedBeforeOutage=engine.Snapshot.Failed;FixtureIo(()=>Directory.Move(c.WatchRoot,c.WatchRoot+".offline"));offline=true;cycles++;Console.WriteLine($"SOAK OFFLINE cycle={cycles} sec={timer.Elapsed.TotalSeconds:F3}");}
   if(i%40==20&&offline)Restore();
   Thread.Sleep(1000);using var process=Process.GetCurrentProcess();process.Refresh();if(i==5){initialMemory=process.PrivateMemorySize64;initialHandles=process.HandleCount;}peakMemory=Math.Max(peakMemory,process.PrivateMemorySize64);peakHandles=Math.Max(peakHandles,process.HandleCount);var s=engine.Snapshot;
   var sample=new{sec=Math.Round(timer.Elapsed.TotalSeconds,3),privateBytes=process.PrivateMemorySize64,workingSet=process.WorkingSet64,handles=process.HandleCount,threads=process.Threads.Count,copied=s.Copied,failed=s.Failed,logLines=engine.Lines.Length,offline,cycles,recovered};samples.Add(sample);Console.WriteLine(JsonSerializer.Serialize(sample));Program.Check(engine.Lines.Length<=50,"soak log unbounded");Program.Check(s.Running,"engine stopped during soak");
  }
  if(offline)Restore();while(recoveryPath!=null){VerifyRecovery();if(recoveryPath!=null)Thread.Sleep(100);}
  }finally{engine.StopAsync().GetAwaiter().GetResult();}
  var logs=Directory.GetFiles(MachineState.Root,"engine*.log");Program.Check(logs.Length<=3&&logs.All(x=>new FileInfo(x).Length<=1048576),"disk logs exceed limits");Program.Check(peakMemory-initialMemory<67108864&&peakHandles-initialHandles<100,"soak resource drift exceeded64MiB/100handles");Program.Check(engine.Snapshot.Failed>0&&engine.Snapshot.Copied>30&&recovered==cycles,"fault/recovery not exercised");
  Program.Check(Directory.GetFiles(c.WatchRoot,"Request*.xml",SearchOption.AllDirectories).Length==30+cycles,"soak source files lost");using(var after=new OwnerLease()){}
  Durable.Write(Path.Combine(root,"samples.json"),JsonSerializer.Serialize(samples,new JsonSerializerOptions{WriteIndented=true}),1048576);Console.WriteLine($"SOAK RESULT requestedSec={seconds} actualSec={timer.Elapsed.TotalSeconds:F3} samples={samples.Count} baselinePrivate={initialMemory} peakPrivate={peakMemory} baselineHandles={initialHandles} peakHandles={peakHandles} copied={engine.Snapshot.Copied} failed={engine.Snapshot.Failed} outageCycles={cycles} verifiedRecoveries={recovered} sourcePreserved=true logFiles={logs.Length} logBytes={logs.Sum(x=>new FileInfo(x).Length)} root={root}");return 0;
 }catch(Exception ex){Console.WriteLine("SOAK FAIL "+ex);return 1;}}
}
